# GET /api/sheets/{sheetId}/tree — the ids of the sheets of its tree (its root first, then the root's descendants).
list:
  class: net.officefloor.hq.app.sheet.ListTree
  govern: [ readonly-transaction ]
import { useEffect, useState } from 'react';
import { useIsFetching, useQuery } from '@tanstack/react-query';
import { listPeople, peopleKey } from '../people/api';
import { usePersonDues } from '../rates/DueTotal';
import { useOverdue } from '../rates/Overdue';
import { formatCents, hundredths, trimmedSum } from '../rates/api';
import { useAsOf } from '../sheet/AsOf';
import { descendantsKey, listDescendants, liveKey } from '../sheet/api';
import { Fig } from '../session/Fig';
import { claimsKey, listClaims } from '../claims/api';
import { STATUSES, statusCount, useGradeDues } from './Summary';

/** A sheet's own figures: each person's names (their name and aliases), due-total and overdue-total as
 *  their row shows them, and per grade and status the figures as the sheet's summary shows them. */
type Figures = { names: string[][]; dues: Array<string | null>; overdues: string[]; grades: Record<string, string>;
  statuses: Record<string, number> };

const nameKey = (name: string) => name.trim().toLowerCase();

/** How many people over the tree: people whose names or aliases match (as names are compared) are one. */
function distinctPeople(names: string[][]): number {
  const parent = names.map((_, i) => i);
  const find = (i: number): number => (parent[i] === i ? i : (parent[i] = find(parent[i])));
  const seen = new Map<string, number>();
  names.forEach((ns, i) => ns.forEach((n) => {
    const k = nameKey(n);
    const j = seen.get(k);
    if (j === undefined) seen.set(k, i);
    else parent[find(i)] = find(j);
  }));
  return names.filter((_, i) => find(i) === i).length;
}

/** As the screen shows the sheet: as of its date while one is set, each sheet as it stood then. */
function useFigures(sheetId: string, user: string): Figures {
  const people = useQuery({ queryKey: peopleKey(sheetId), queryFn: () => listPeople(sheetId) });
  const claims = useQuery({ queryKey: claimsKey(sheetId), queryFn: () => listClaims(sheetId) });
  const statuses = Object.fromEntries(STATUSES.map((s) => [s, statusCount(claims.data, s)]));
  return { names: (people.data ?? []).map((p) => [p.name, ...p.aliases]), dues: usePersonDues(sheetId, user),
    overdues: useOverdue(sheetId, user).perPerson, grades: useGradeDues(sheetId, user), statuses };
}

/** Works out one descendant sheet's own figures and hands them up; shows nothing. */
function Descendant({ sheetId, user, report }: { sheetId: string; user: string; report: (id: string, f: Figures) => void }) {
  const f = useFigures(sheetId, user);
  useEffect(() => report(sheetId, f), [sheetId, JSON.stringify(f)]);
  return null;
}

/** The consolidated figures over the sheet and all its descendants (its children, theirs, ...): the
 *  number of people, each counted once (people whose names or aliases match, as names are compared, are
 *  one); the due- and overdue-total of every person of the tree as their row shows it, added up leaving
 *  out the single highest and lowest over the whole tree when three or more have one; per grade,
 *  each sheet's due-total of that grade (retired people left out, as its summary shows it) added up; per
 *  status, the number of claims in it over the tree.
 *  While the screen shows the sheet as of a date, every sheet of the tree is as it stood at the end of
 *  that day, with that date as its today; the tree itself is the one the sheets' parents make now. */
export function Consolidated({ sheetId, user }: { sheetId: string; user: string }) {
  const [asOf] = useAsOf();
  // The tree is the one the sheets' parents make now, even while the screen shows a date.
  const live = asOf !== '';
  const own = useFigures(sheetId, user);
  const descendants = useQuery({ queryKey: liveKey(descendantsKey(sheetId), live), queryFn: () => listDescendants(sheetId, live) });
  const ids = descendants.data ?? [];
  const [reported, setReported] = useState<Record<string, Figures>>({});
  const report = (id: string, f: Figures) => setReported((r) => ({ ...r, [id]: f }));
  // A descendant's figures count once its own queries have been read afresh.
  const fetching = useIsFetching({ predicate: (q) => q.queryKey[0] === 'sheet' && ids.includes(q.queryKey[1] as string) });
  const ready = descendants.isSuccess && fetching === 0 && ids.every((id) => reported[id] !== undefined);
  const all = [own, ...ids.map((id) => reported[id]).filter((f): f is Figures => f !== undefined)];
  // Every grade of any sheet of the tree: this sheet's, then those only the others have.
  const grades = [...new Set(all.flatMap((f) => Object.keys(f.grades)))];
  const sum = (pick: (f: Figures) => string) => formatCents(all.reduce((t, f) => t + hundredths(pick(f)), 0n));
  return (
    <p>
      {ids.map((id) => <Descendant key={id} sheetId={id} user={user} report={report} />)}
      Consolidated: people <span data-testid="consolidated-people-count">{ready ? distinctPeople(all.flatMap((f) => f.names)) : ''}</span>
      {' · '}due <span data-testid="consolidated-due-total"><Fig>{ready ? trimmedSum(all.flatMap((f) => f.dues)) : ''}</Fig></span>
      {' · '}overdue <span data-testid="consolidated-overdue-total"><Fig>{ready ? trimmedSum(all.flatMap((f) => f.overdues)) : ''}</Fig></span>
      {grades.map((g) => (
        <span key={g}>{' · '}grade {g} due <span data-testid={`consolidated-grade-${g}-due-total`}>
          <Fig>{ready ? sum((f) => f.grades[g] ?? '0.00') : ''}</Fig></span></span>
      ))}
      {STATUSES.map((s) => (
        <span key={s}>{' · '}{s} <span data-testid={`consolidated-status-${s}-count`}>
          {ready ? all.reduce((t, f) => t + f.statuses[s], 0) : ''}</span></span>
      ))}
    </p>
  );
}
import { useEffect, useRef, useState } from 'react';
import { useIsFetching, useQuery, useQueryClient } from '@tanstack/react-query';
import { useCapOf } from '../pools/cap';
import { claimsKey, listClaims, liveClaims } from '../claims/api';
import { gradeOn, listPeople, peopleKey, shownName } from '../people/api';
import { listRates, personDue, rateByGrade, ratesKey, showDue } from '../rates/api';
import { heldOf } from '../rates/shares';
import { useFloor, useLate } from '../settings/api';
import { listTree, sheetKey, treeKey, useSheetToday } from '../sheet/api';

/** A person as the search finds them: their name, aliases and due-total as their row shows it. */
type Found = { name: string; shown: string; aliases: string[]; due: string };

/** Everyone on a sheet in list order, with their due-total as that sheet's list shows it; undefined until read. */
function useSheetPeople(sheetId: string, user: string): Found[] | undefined {
  const people = useQuery({ queryKey: peopleKey(sheetId), queryFn: () => listPeople(sheetId) });
  const claims = useQuery({ queryKey: claimsKey(sheetId), queryFn: () => listClaims(sheetId) });
  const rates = useQuery({ queryKey: ratesKey(sheetId), queryFn: () => listRates(sheetId) });
  const floor = useFloor(sheetId);
  const today = useSheetToday(sheetId, user);
  const capOf = useCapOf(sheetId, today);
  const charges = useLate(sheetId, today);
  if (!people.isSuccess || !claims.isSuccess || !rates.isSuccess || today === '') return undefined;
  const byGrade = rateByGrade(rates.data, today);
  return people.data.map((p) => ({
    name: p.name,
    shown: shownName(p),
    aliases: p.aliases,
    due: showDue(personDue(liveClaims(claims.data.filter((c) => c.personId === p.id), [p]),
      rates.data, (d) => gradeOn(p, d), byGrade.get(p.grade), floor, charges, capOf(p.id),
      heldOf(p.id, claims.data, people.data, rates.data, floor, charges))),
  }));
}

/** Works out one sheet's people and hands them up; shows nothing. */
function TreeSheet({ sheetId, user, report }: { sheetId: string; user: string; report: (id: string, f: Found[]) => void }) {
  const found = useSheetPeople(sheetId, user);
  const seen = JSON.stringify(found ?? null);
  useEffect(() => {
    if (found !== undefined) report(sheetId, found);
  }, [sheetId, seen]);
  return null;
}

/** A search box and a button that list, over the sheet and every other sheet of its tree, everyone
 *  whose name or an alias contains the typed text (case ignored), one line each `<sheet id> <name (grade)>
 *  <due-total>`: the sheet's own people first in list order, then the other sheets' by sheet id. The
 *  count is cleared while a search runs; every sheet is read afresh for it. */
export function TreeSearch({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const [text, setText] = useState('');
  // The search running or done: the text searched for and the tree's sheets (null: still being read).
  const [run, setRun] = useState<{ n: number; text: string; ids: string[] | null } | null>(null);
  const [failed, setFailed] = useState(false);
  const [reported, setReported] = useState<Record<string, Found[]>>({});
  const runs = useRef(0);

  // Another sheet loaded: the last search was over another tree.
  useEffect(() => {
    runs.current++;
    setRun(null);
    setFailed(false);
  }, [sheetId]);

  const search = async () => {
    const n = ++runs.current;
    const typed = text;
    setRun({ n, text: typed, ids: null });
    setReported({});
    setFailed(false);
    try {
      const tree = await queryClient.fetchQuery({ queryKey: treeKey(sheetId), queryFn: () => listTree(sheetId), staleTime: 0 });
      // Every sheet of the tree is read afresh, also those read before.
      await Promise.all(tree.map((id) => queryClient.invalidateQueries({ queryKey: sheetKey(id), refetchType: 'all' })));
      if (runs.current !== n) return;
      const others = tree.filter((id) => id !== sheetId).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
      setRun({ n, text: typed, ids: [sheetId, ...others] });
    } catch {
      if (runs.current === n) {
        setRun(null);
        setFailed(true);
      }
    }
  };

  const ids = run?.ids ?? [];
  const fetching = useIsFetching({ predicate: (q) => q.queryKey[0] === 'sheet' && ids.includes(q.queryKey[1] as string) });
  const ready = run !== null && run.ids !== null && fetching === 0 && ids.every((id) => reported[id] !== undefined);
  const needle = (run?.text ?? '').toLowerCase();
  const lines = ready
    ? ids.flatMap((id) => reported[id]
      .filter((f) => [f.name, ...f.aliases].some((s) => s.toLowerCase().includes(needle)))
      .map((f) => `${id} ${f.shown} ${f.due}`))
    : [];

  return (
    <div>
      {run?.ids?.map((id) => (
        <TreeSheet key={`${run.n}-${id}`} sheetId={id} user={user}
          report={(sid, f) => setReported((r) => ({ ...r, [sid]: f }))} />
      ))}
      <label>
        Search the tree{' '}
        <input data-testid="search-name" value={text} onChange={(e) => {
          setText(e.target.value);
          setFailed(false);
        }} />
      </label>{' '}
      <button type="button" data-testid="search" onClick={() => void search()}>
        Search
      </button>{' '}
      Found <span data-testid="search-count">{ready ? lines.length : ''}</span>
      {failed && <span data-testid="search-error"> The tree could not be searched.</span>}
      <ul>
        {lines.map((l, i) => (
          <li key={i} data-testid="search-line">{l}</li>
        ))}
      </ul>
    </div>
  );
}
